mapper.select:
SELECT SUM(old_user) AS oldUserCnt,
       SUM(new_user) AS newUserCnt
FROM (SELECT IF(COUNT(DISTINCT DATE(tlal.create_time)) > 1, 1, 0) AS old_user,
             IF(
                     COUNT(DISTINCT DATE(tlal.create_time)) = 1
                         AND MAX(tlal.create_time) >= #{param.startDate}
                         AND MAX(tlal.create_time) <= #{param.endDate},
                     1,
                     0
             )                                                    AS new_user
      FROM t_link tl
               INNER JOIN t_link_access_logs tlal
                          ON tl.full_short_url = tlal.full_short_url
      WHERE tlal.full_short_url = #{param.fullShortUrl}
        AND tl.gid = #{param.gid}
        AND tl.enable_status = #{param.enableStatus}
        AND tl.del_flag = '0'
      GROUP BY tlal.user) AS user_counts;

SELECT
tlal.user,
IF(MIN(tlal.create_time) BETWEEN #{startDate} AND #{endDate}, '新访客', '老访客') AS uvType
FROM
t_link tl
INNER JOIN t_link_access_logs tlal
ON tl.full_short_url = tlal.full_short_url
WHERE
tlal.full_short_url = #{fullShortUrl}
AND tl.gid = #{gid}
AND tl.del_flag = '0'
AND tl.enable_status = #{enableStatus}
AND tlal.user IN

    #{item}

GROUP BY
tlal.user;

SELECT tlal.user, IF(MIN(tlal.create_time) BETWEEN #{startDate} AND #{endDate}, '新访客', '老访客') AS uvType FROM t_link tl INNER JOIN t_link_access_logs tlal ON tl.full_short_url = tlal.full_short_url WHERE tl.gid = #{gid} AND tl.del_flag = '0' AND tl.enable_status = '0' AND tlal.user IN
#{item}
GROUP BY tlal.user;

SELECT COUNT(tlal.user)          AS pv,
       COUNT(DISTINCT tlal.user) AS uv,
       COUNT(DISTINCT tlal.ip)   AS uip
FROM t_link tl
         INNER JOIN t_link_access_logs tlal
                    ON tl.full_short_url = tlal.full_short_url
WHERE tlal.full_short_url = #{param.fullShortUrl}
  AND tl.gid = #{param.gid}
  AND tl.del_flag = '0'
  AND tl.enable_status = #{param.enableStatus}
  AND tlal.create_time BETWEEN #{param.startDate} AND #{param.endDate}
GROUP BY tlal.full_short_url,
         tl.gid;

SELECT tlal.*
FROM t_link tl
         INNER JOIN t_link_access_logs tlal
                    ON tl.full_short_url = tlal.full_short_url
WHERE tl.gid = #{param.gid}
  AND tl.del_flag = '0'
  AND tl.enable_status = '0'
  AND tlal.create_time BETWEEN #{param.startDate} AND #{param.endDate}
ORDER BY tlal.create_time DESC;
